case .voiceWarm:
    try fields(payload, allowed: ["profile", "lease", "active"], required: ["profile", "lease", "active"])
    var request = DirectHermesHTTPRequest(path: "/api/audio/tts-lease", method: .post,
                                          query: try queryItems(["profile": payload["profile"]!]),
