class _Room(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    roomId: str = Field(pattern=r"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$")

class _Poll(_Stream):
    after: StrictInt = Field(ge=0, le=9_007_199_254_740_991)
    limit: StrictInt = Field(ge=1, le=8)

class _Bind(_WorkflowBody):
    role: str = Field(pattern=_KEY)
    agentId: str | None = Field(pattern=r"^[a-z0-9][a-z0-9_-]{0,63}$")

class _Events(_RunBody):
    after: StrictInt = Field(ge=0, le=2**62)
    limit: StrictInt = Field(default=100, ge=1, le=200)

class _Control(_RunBody):
    action: Literal["pause", "resume", "cancel", "retry"]
    expectedVersion: StrictInt = Field(ge=1, le=2**62)

class _Templates(_Strict):
    # Dev Factory templates are listed only for an app that asks (older apps can't open them).
    includeCode: StrictBool = False

class _Use(_Strict):
    templateId: str = Field(pattern=r"^[a-z0-9][a-z0-9-]{0,63}$")
    name: str | None = Field(default=None, min_length=1, max_length=80)

class _SaveTemplate(_WorkflowBody):
    name: str = Field(min_length=1, max_length=80)
    description: str | None = Field(default=None, max_length=1000)

class _WorkspaceBody(_StrictBody):
    workspace_id: str = Field(
        min_length=1,
        max_length=80,
        pattern=r"^[A-Za-z0-9][A-Za-z0-9._:-]{0,79}$",
    )
